def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count observed outcomes
    cc = cd = dc = dd = 0
    for mine, opp in history:
        if mine == 'C' and opp == 'C':
            cc += 1
        elif mine == 'C' and opp == 'D':
            cd += 1
        elif mine == 'D' and opp == 'C':
            dc += 1
        else:
            dd += 1

    # Estimate opponent's cooperation rate
    opp_c = cc + dc
    opp_total = n
    opp_coop_rate = opp_c / opp_total

    # Early-game: probe and establish cooperation
    if n < 10:
        # Alternate: start with C, then test
        if n == 1:
            return 'C'
        if n == 2:
            return 'C'
        if n == 3:
            return 'C'
        # If opponent has been cooperative, keep cooperating
        if opp_coop_rate >= 0.6:
            return 'C'
        return 'D'

    # Detect unconditional always-D opponents
    if cd == 0 and cc == 0 and dc > 0:
        return 'D'

    # Forgive but remember: cooperate if opponent cooperates most of the time
    # Use a sliding window of last 20 moves
    window = history[-20:]
    w_cc = w_cd = w_dc = w_dd = 0
    for mine, opp in window:
        if mine == 'C' and opp == 'C':
            w_cc += 1
        elif mine == 'C' and opp == 'D':
            w_cd += 1
        elif mine == 'D' and opp == 'C':
            w_dc += 1
        else:
            w_dd += 1

    w_opp_c = w_cc + w_dc
    w_opp_rate = w_opp_c / len(window)

    # Temptation check: if opponent cooperates a lot, exploit occasionally
    if w_opp_rate >= 0.85 and n > 50:
        # Rarely defect to gain points, but not too often
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Reciprocal: if opponent cooperated last round, cooperate
    last_mine, last_opp = history[-1]
    if last_opp == 'C':
        # Maybe punish occasional defection with immediate retaliation
        if w_cd > w_dc and w_cd >= 2:
            return 'D'
        return 'C'
    else:
        # Opponent defected: retaliate, but consider forgiveness
        # Count consecutive recent opponent defections
        consec_d = 0
        for mine, opp in reversed(history):
            if opp == 'D':
                consec_d += 1
            else:
                break
        if consec_d == 1:
            # Immediate retaliation
            return 'D'
        if consec_d == 2:
            # Second retaliation
            return 'D'
        # Forgive after sustained punishment
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Fallback
    if opp_coop_rate >= 0.5:
        return 'C'
    return 'D'

